3160	export interface DBLevelingMultiplier {
3161		/** id del rol o del canal, según la lista en la que viva. */
3162		id: string;
3163		/** Factor aplicado a la XP concedida. Rango [0.1, 10]. */
3164		multiplier: number;
3165	}
3166	
3167	/** Recompensa: al alcanzar `level` se conceden estos roles. */
3168	export interface DBLevelingReward {
3169		level: number;
3170		role_ids: string[];
3171	}
3172	
3173	/**
3174	 * Requisitos que un miembro debe cumplir para ganar XP de UNA fuente (texto o
3175	 * voz — cada una lleva su PROPIA copia dentro de `DBLevelingSource`, no es un
3176	 * único bloque compartido). Todos con "0 / false / lista vacía = sin
3177	 * requisito", así que un guild que no los toque no nota absolutamente nada:
3178	 * el bloque entero es opt-in.
3179	 *
3180	 * Existen para el abuso, no para la burocracia — el caso que los motiva es la
3181	 * cuenta recién creada que entra, farmea nivel a base de mensajes de una letra
3182	 * y se va.
3183	 */
3184	export interface DBLevelingRequirements {
3185		/**
3186		 * Segundos que el miembro debe llevar EN EL SERVIDOR antes de ganar XP.
3187		 * Sale de `joined_at` del miembro, que ya está en la caché de miembros:
3188		 * ninguna petición extra a Discord. 0 = sin requisito.
3189		 */
3190		min_membership_seconds: number;
3191		/**
3192		 * Antigüedad mínima de la CUENTA de Discord, en segundos. Se deduce del
3193		 * snowflake del propio id de usuario (los 42 bits altos son el timestamp),
3194		 * así que tampoco cuesta ninguna petición. 0 = sin requisito.
3195		 */
3196		min_account_age_seconds: number;
3197		/** SOLO TEXTO. Caracteres mínimos del mensaje, ya recortado. 0 = cualquiera. */
3198		min_message_length: number;
3199		/** SOLO TEXTO. Descarta el mensaje cuyo contenido, quitado el enlace, queda vacío. */
3200		ignore_link_only: boolean;
3201		/** SOLO TEXTO. Descarta el mensaje sin texto que solo trae adjuntos. */
3202		ignore_attachment_only: boolean;
3203		/** SOLO TEXTO. Descarta el mensaje que solo son emojis (unicode o custom) o un sticker. */
3204		ignore_sticker_or_emoji_only: boolean;
3205		/** SOLO TEXTO. Descarta el mensaje que empieza por el prefijo del servidor. */
3206		ignore_commands: boolean;
3207		/** Roles que se saltan TODOS los requisitos anteriores (staff, boosters…). */
3208		bypass_role_ids: string[];
3209	}
3210	
3211	/** Cuándo NO cuenta el tiempo en voz para ganar XP. */
3212	export interface DBLevelingVoiceRules {
3213		/** Solo en el canal (o sólo con bots) no da XP. */
3214		ignore_alone: boolean;
3215		ignore_muted: boolean;
3216		ignore_deafened: boolean;
3217	}
3218	
3219	/**
3220	 * Reglas de concesión de XP de UNA fuente (texto o voz): tasa, requisitos de
3221	 * elegibilidad, exclusiones y multiplicadores. Los CUATRO modos de `xp_mode`
3222	 * persisten SIEMPRE los dos bloques (`text` y `voice`) — el modo decide
3223	 * cuáles CONCEDEN XP, no cuáles existen (ver la tabla de resolución en el
3224	 * TSDoc de `DBModuleLeveling`).
3225	 *
3226	 * `interval_seconds` significa cosas distintas en cada fuente y por eso NO se
3227	 * llama `cooldown`:
3228	 *   - texto: ventana antispam; sólo el primer mensaje de la ventana da XP.
3229	 *   - voz: duración del tick; cada tick completo en voz concede una tirada.
3230	 *
3231	 * Con `metric: "time"` (sólo tiene sentido en la fuente de VOZ) esta fuente
3232	 * deja de tirar XP del todo: `min`/`max` no se usan y lo que gobierna el
3233	 * nivel son los MINUTOS de `voice_seconds` — ver `LevelingVoiceMetric` y
3234	 * `resolveVoiceMetric`.
3235	 */
3236	export interface DBLevelingSource {
3237		/**
3238		 * Qué magnitud mide esta fuente (ver `LevelingVoiceMetric`). Sólo tiene
3239		 * efecto en la fuente de VOZ; en el bloque de texto se IGNORA (siempre
3240		 * `"xp"`) y se persiste igual por simetría de forma, igual que
3241		 * `voice_rules` más abajo. Nunca se lee a pelo: resuélvelo con
3242		 * `resolveVoiceMetric`, que además fuerza `"xp"` en `xp_mode: "unified"`.
3243		 */
3244		metric: LevelingVoiceMetric;
3245		/** XP mínima por concesión. */
3246		min: number;
3247		/** XP máxima por concesión (>= min; igual a `min` = cantidad fija). */
3248		max: number;
3249		interval_seconds: number;
3250		requirements: DBLevelingRequirements;
3251		/** Canales donde no se gana XP con esta fuente. */
3252		excluded_channel_ids: string[];
3253		/** Quien tenga uno de estos roles no gana XP con esta fuente. */
3254		excluded_role_ids: string[];
3255		role_multipliers: DBLevelingMultiplier[];
3256		channel_multipliers: DBLevelingMultiplier[];
3257		/**
3258		 * Sólo se aplica a la fuente de voz; en el bloque de texto se IGNORA. Se
3259		 * persiste igual en los dos bloques por simetría de forma (y para que
3260		 * configurarlo en `voice` y luego cambiar de modo no pierda nada).
3261		 */
3262		voice_rules: DBLevelingVoiceRules;
3263	}
3264	
3265	/** Recompensas de nivel de UNA progresión: roles concedidos al alcanzar cada nivel de la lista. */
3266	export interface DBLevelingRewards {
3267		enabled: boolean;
3268		stacking: LevelingRewardStacking;
3269		levels: DBLevelingReward[];
3270	}
3271	
3272	/** Aviso de subida de nivel de UNA progresión. */
3273	export interface DBLevelingAnnounce {
3274		enabled: boolean;
3275		target: LevelingAnnounceTarget;
3276		/** Sólo se usa con `target: "channel"`. */
3277		channel_id: string | null;
3278		/** Tokens admitidos: {user} {mention} {level} {xp} {guild} {rank}. */
3279		content: string;
3280		/** Segundos hasta borrar el anuncio. `null` o `0` = no se borra. */
3281		delete_after_seconds: number | null;
3282	}
3283	
3284	/**
3285	 * Curva, recompensas y anuncio de UNA progresión (un nivel). El número de
3286	 * progresiones ACTIVAS lo decide `xp_mode`: una sola en `text_only`/
3287	 * `voice_only`/`unified`, dos (`progression_text` + `progression_voice`) en
3288	 * `separate`. Los cuatro modos persisten SIEMPRE los dos bloques.
3289	 */
3290	export interface DBLevelingProgression {
3291		/** `formula`: curva automática con `curve_multiplier`. `manual`: la tabla
3292		 *  de `manual_thresholds`. */
3293		curve_mode: LevelingCurveMode;
3294		/** Factor de dificultad de la curva cuando `curve_mode` es `"formula"`;
3295		 *  se ignora en `"manual"`. Ver `xpForNextLevel` en `leveling/curve.ts`.
3296		 *  Rango [0.01, 100]. */
3297		curve_multiplier: number;
3298		/**
3299		 * Umbrales ACUMULADOS, en orden ascendente: el índice 0 es lo que cuesta
3300		 * llegar al nivel 1, el índice 1 al nivel 2, etc. En XP, o en MINUTOS si
3301		 * la progresión mide tiempo (`LevelingVoiceMetric`).
3302		 *
3303		 * Al pasar del último umbral NO hay más niveles: el miembro se queda en
3304		 * el máximo definido y sigue acumulando XP/minutos sin subir. Es la
3305		 * decisión del dueño del proyecto, y hay que contarla en la interfaz.
3306		 *
3307		 * Lista vacía con `curve_mode: "manual"` = nadie pasa del nivel 0; es un
3308		 * estado válido (a medio configurar), no un error. Se ignora en
3309		 * `curve_mode: "formula"`.
3310		 */
3311		manual_thresholds: number[];
3312		rewards: DBLevelingRewards;
3313		announce: DBLevelingAnnounce;
3314	}
3315	
3316	/**
3317	 * Config POR-GUILD del módulo de niveles (XP y rangos). El almacenamiento de
3318	 * XP vive SIEMPRE en Postgres (`leveling.user_stats`, `text_xp`/`voice_xp`
3319	 * separados); este documento es sólo la CONFIGURACIÓN.
3320	 *
3321	 * `xp_mode` es la PRIMERA decisión del admin y de ella depende la forma
3322	 * entera de la interfaz. Cambiarla en el dashboard NUNCA destruye
3323	 * configuración ni recalcula nada en masa (recálculo perezoso, ver
3324	 * `leveling/curve.ts`): los CUATRO bloques (`text`, `voice`,
3325	 * `progression_text`, `progression_voice`) se persisten SIEMPRE, los use o no
3326	 * el modo activo. Qué bloque es el EFECTIVO para cada modo es una regla
3327	 * ÚNICA — no reimplementar el switch en bot/dashboard, usar
3328	 * `resolveLevelingScope`/`levelingProgressionFor`:
3329	 *
3330	 * | Modo         | Fuentes que conceden | Progresión(es) efectiva(s)                    |
3331	 * |--------------|-----------------------|------------------------------------------------|
3332	 * | `text_only`  | `text`                | `progression_text`                              |
3333	 * | `voice_only` | `voice`               | `progression_voice`                             |
3334	 * | `unified`    | `text` y `voice`      | `progression_text` (nivel = text_xp + voice_xp) |
3335	 * | `separate`   | `text` y `voice`      | `progression_text` / `progression_voice`        |
3336	 *
3337	 * ⚠️ En `unified` la progresión activa es `progression_text` — deliberado:
