// viven en su propia colección y no pasan por esta caché.
func MarshalModuleNotifier(m dbguild.ModuleNotifier) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
	out["enabled_since"] = nullableDateField(m.EnabledSince)
	out["updated_at"] = dateField(m.UpdatedAt.Time)
	return out, nil
}

// MarshalModuleTTS serializa el subdocumento `dbguild.ModuleTTS`. Mismo molde
// que `MarshalModuleAutomation`: los escalares pasan por SerializeValue, el
// nullable de primer nivel (`required_role_id`) por `nullableStringField` para
// que nil → "" (el convenio `serializeValue(null) === ""` de Node, que al
// volver da otra vez un `*string` nil), y `updated_at` lleva el prefijo
// `__DATE__:` para que el viaje de ida y vuelta no pierda precisión.
//
// `commands_global` y `commands` van por `putJSONInline`, como en tempvoice y
// moderation: son los únicos anidados. Esta lista es MANUAL — un campo que
// falte aquí se sirve en blanco desde caché durante todo el TTL aunque Mongo
// lo tenga bien.
func MarshalModuleTTS(m dbguild.ModuleTTS) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
	out["enabled_since"] = nullableDateField(m.EnabledSince)
	out["require_voice"] = SerializeValue(m.RequireVoice)
	out["language"] = SerializeValue(m.Language)
	out["speed"] = SerializeValue(m.Speed)
	out["say_name"] = SerializeValue(m.SayName)
	out["max_chars"] = SerializeValue(m.MaxChars)
	out["repeated_chars"] = SerializeValue(m.RepeatedChars)
	out["skip_emoji"] = SerializeValue(m.SkipEmoji)
	out["required_role_id"] = nullableStringField(m.RequiredRoleID)
	putJSONInline(out, "commands_global", m.CommandsGlobal)
	putJSONInline(out, "commands", m.Commands)
	out["updated_at"] = dateField(m.UpdatedAt.Time)
	return out, nil
}

// MarshalModuleModeration serializes a typed `dbguild.ModuleModeration` subdoc.
// Mirrors the greeter/tempvoice/giveaway marshallers: scalars (schema_version,
// enabled, track_native_actions) go through SerializeValue; `command_mode` is a
// named-string enum so it's coerced with `string(...)` (SerializeValue's type
// switch would miss the named type and JSON-quote it, matching how the music
// marshaller writes `loop`); every nested object / map (`commands_global`,
// `commands`, `mute`, `automod` y los siete bloques del v3 —`protection`,
// `escalation`, `effects`, `raid`, `gate`, `antinuke`, `lockdown`—) goes
// through putJSONInline (JSON); the single
// top-level nullable string (`log_channel_id`) uses `nullableStringField` so nil
// → "" (the Node `serializeValue(null) === ""` convention, round-tripping back to
// a nil `*string`); `updated_at` uses the `__DATE__:` prefix so the round-trip is
// lossless (same as greeter). The nested nullables (`mute.role_id`, each
// command's `dm_embed.color`) ride inside their JSON-encoded parent, so JSON
// `null` round-trips them losslessly.
func MarshalModuleModeration(m dbguild.ModuleModeration) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
	out["enabled_since"] = nullableDateField(m.EnabledSince)
	out["command_mode"] = string(m.CommandMode)
	putJSONInline(out, "commands_global", m.CommandsGlobal)
	putJSONInline(out, "commands", m.Commands)
	putJSONInline(out, "mute", m.Mute)
	out["log_channel_id"] = nullableStringField(m.LogChannelID)
	out["track_native_actions"] = SerializeValue(m.TrackNativeActions)
	putJSONInline(out, "automod", m.Automod)
	// v3: los siete bloques anidados nuevos. Cada uno necesita SU línea — un
	// bloque que falte aquí desaparece del cache-hit durante la hora entera de
	// TTL (el campo llega vacío a la dashboard aunque en Mongo esté bien).
	putJSONInline(out, "protection", m.Protection)
	putJSONInline(out, "escalation", m.Escalation)
	putJSONInline(out, "effects", m.Effects)
	putJSONInline(out, "raid", m.Raid)
	putJSONInline(out, "gate", m.Gate)
	putJSONInline(out, "antinuke", m.Antinuke)
	putJSONInline(out, "lockdown", m.Lockdown)
	out["updated_at"] = dateField(m.UpdatedAt.Time)
	return out, nil
}

// MarshalModuleLeveling serializa el subdocumento `dbguild.ModuleLeveling`.
// Mismo molde que `MarshalModuleTempvoice`: los escalares (schema_version,
// enabled, curve_multiplier) pasan por SerializeValue; `xp_mode` y
// `command_mode` son enums de string nombrado, así que se fuerzan con
// `string(...)` — `SerializeValue` los perdería por su switch de tipos y
// los citaría como JSON, igual que `loop` en music o `command_mode` en
// tempvoice; todo objeto/mapa/array anidado (`text`, `voice`,
// `voice_rules`, las dos listas de multiplicadores, `announce`, `rewards`,
// `rank_card`, `commands_global`, `commands`) va por `putJSONInline`
// (JSON); `updated_at` lleva el prefijo `__DATE__:` para que el viaje de
// ida y vuelta no pierda precisión (igual que tempvoice).
func MarshalModuleLeveling(m dbguild.ModuleLeveling) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
	out["enabled_since"] = nullableDateField(m.EnabledSince)
	out["xp_mode"] = string(m.XPMode)
	putJSONInline(out, "text", m.Text)
	putJSONInline(out, "voice", m.Voice)
	out["curve_multiplier"] = SerializeValue(m.CurveMultiplier)
	putJSONInline(out, "voice_rules", m.VoiceRules)
	putJSONInline(out, "excluded_channel_ids", m.ExcludedChannelIDs)
	putJSONInline(out, "excluded_role_ids", m.ExcludedRoleIDs)
	putJSONInline(out, "role_multipliers", m.RoleMultipliers)
	putJSONInline(out, "channel_multipliers", m.ChannelMultipliers)
	putJSONInline(out, "announce", m.Announce)
	putJSONInline(out, "rewards", m.Rewards)
	putJSONInline(out, "rank_card", m.RankCard)
	putJSONInline(out, "commands_global", m.CommandsGlobal)
	putJSONInline(out, "commands", m.Commands)
	out["command_mode"] = string(m.CommandMode)
	out["updated_at"] = dateField(m.UpdatedAt.Time)
	return out, nil
}

// nullableStringField encodes a `*string` the way the Node cache writer's
// `serializeValue` does: nil → "" (empty field), else the raw string as-is.
// On read, DeserializeValue("") → nil, round-tripping back to a nil pointer.
func nullableStringField(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

// nullableIntField — el gemelo de `nullableStringField` para `*int`: nil → ""
// (DeserializeValue("") = nil → puntero nil al decodificar el hash), número →
// su forma serializada normal.
func nullableIntField(p *int) string {
	if p == nil {
		return ""
	}
	return SerializeValue(*p)
}

// nullableDateField encodes el `enabled_since` opcional con la misma
// convención que el resto de nulos del hash: `__DATE__:<ISO>` cuando hay
// fecha, cadena vacía cuando no — `DeserializeValue("")` devuelve nil, que
// decodifica al puntero nil del struct. Evita repetir el if/else en los ocho

package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// UpdateModuleTempvoiceBody mirrors the Node `updateModuleTempVoiceSchema` (a
// `.strict()` object of `.optional()` fields). Unlike the READ schema, the
// PATCH schema excludes only `schema_version` and `updated_at` (server-managed).
// The top-level `name_blacklist`, `panel` and `command_mode` (added in v3/v4/v7)
// ARE patchable — omitting them here made the strict decoder reject them as
// `unrecognized_keys` on any PATCH that included them (e.g. saving the panel from
// the dashboard) → 400. Every field is a pointer so the strict decoder can validate
// the shape; the handler then re-decodes the SAME raw body as `map[string]any`,
// which the repository merges into the existing subdoc via
// `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the body is left
// alone; an explicit `false`/`0`/`""`/`null` is applied and overrides the
// stored value; nested objects recurse (so a partial
// `{"defaults":{"bitrate":96000}}` PATCH preserves the other defaults);
// slices (`creators`) replace wholesale; maps merge per-key.
//
// PER OLA-3 NOTE: the greeter/logs/music bodies bind via Fiber's default
// decoder (silently drops unknown keys, parity with Mongoose) — only
// modmail/tempvoice/giveaway/moderation carry the strict unknown-key
// rejection. The nested field types are the full `dbguild.Tempvoice*`
// shapes: every zod PATCH sub-schema matches its parent type
// field-for-field, so no valid key is rejected. Go's json decoder does
// NOT enforce zod's REQUIRED-ness inside a present nested object, so a
// partial command entry that Node would 400 is accepted here and the
// missing leaves stay zero — the same non-strict-required behaviour
// every Go module body has.
type UpdateModuleTempvoiceBody struct {
	Enabled        *bool                                `json:"enabled,omitempty"`
	Creators       *[]dbguild.TempvoiceCreator          `json:"creators,omitempty"`
	NameBlacklist  *[]string                            `json:"name_blacklist,omitempty"`
	Panel          *dbguild.TempvoicePanel              `json:"panel,omitempty"`
	CommandMode    *dbguild.TempvoiceCommandMode        `json:"command_mode,omitempty"`
	Defaults       *dbguild.TempvoiceDefaults           `json:"defaults,omitempty"`
	CommandsGlobal *dbguild.TempvoiceCommandAccess      `json:"commands_global,omitempty"`
	Commands       *map[string]dbguild.TempvoiceCommand `json:"commands,omitempty"`
}

