package dbguild

import (
	"encoding/json"
	"math"
	"testing"
)

// TestNormalizeGreeter_NilReceiver — defensivo, igual que NormalizeTickets.
func TestNormalizeGreeter_NilReceiver(t *testing.T) {
	NormalizeGreeter(nil) // no debe entrar en pánico
}

// legacyGreeter reproduce lo que Mongo devuelve para un guild v9/v10: bloques
// que existen pero nunca se escribieron enteros, así que decodifican al valor
// cero de Go — enums vacíos, slices nil y un lienzo 0x0.
func legacyGreeter() ModuleGreeter {
	return ModuleGreeter{
		SchemaVersion: 9,
		Enabled:       true,
		Welcome: GreeterMessageConfig{
			Enabled: true,
			Message: GreeterMessage{Content: "¡Hola {user}!"},
		},
	}
}

// TestNormalizeGreeter_LegacyDoc 🛡️ — un doc legacy sale del normalizador con
// la forma que el dashboard y el bot esperan. Sin esto: `mode: ""` no casa con
// ningún modo del renderer (el bot no publica nada mientras el dashboard lo
// pinta como `plain`), y `elements: null` revienta el `.map()` del dashboard y
// el `for..of` del bot.
func TestNormalizeGreeter_LegacyDoc(t *testing.T) {
	g := legacyGreeter()
	NormalizeGreeter(&g)

	if g.Welcome.Message.Mode != GreeterModePlain {
		t.Fatalf("welcome.message.mode = %q, want %q", g.Welcome.Message.Mode, GreeterModePlain)
	}
	if g.Welcome.DM.Message.Mode != GreeterModePlain {
		t.Fatalf("welcome.dm.message.mode = %q, want %q", g.Welcome.DM.Message.Mode, GreeterModePlain)
	}
	if g.Welcome.Image.Mode != GreeterImageBasic {
		t.Fatalf("welcome.image.mode = %q, want %q", g.Welcome.Image.Mode, GreeterImageBasic)
	}
	if g.Welcome.Image.Canvas.Elements == nil {
		t.Fatal("welcome.image.canvas.elements sigue nil (emitiría null en JSON)")
	}
	if g.Welcome.Image.Canvas.Width != 1024 || g.Welcome.Image.Canvas.Height != 500 {
		t.Fatalf("canvas = %dx%d, want 1024x500", g.Welcome.Image.Canvas.Width, g.Welcome.Image.Canvas.Height)
	}
	if g.JoinRoles.RolesID == nil {
		t.Fatal("join_roles.roles_id sigue nil")
	}
	if len(g.Variables.Allowed) != len(DefaultGreeterVariables()) {
		t.Fatalf("variables.allowed = %v, want los %d por defecto", g.Variables.Allowed, len(DefaultGreeterVariables()))
	}
	// Goodbye y boost reciben el mismo trato.
	if g.Goodbye.Message.Mode != GreeterModePlain || g.Boost.Message.Mode != GreeterModePlain {
		t.Fatalf("goodbye/boost mode = %q/%q, want plain", g.Goodbye.Message.Mode, g.Boost.Message.Mode)

