// MarshalModuleLeveling serializa el subdocumento `dbguild.ModuleLeveling`.
// Mismo molde que `MarshalModuleTempvoice`: los escalares (schema_version,
// enabled, curve_multiplier) pasan por SerializeValue; `xp_mode` y
// `command_mode` son enums de string nombrado, así que se fuerzan con
// `string(...)` — `SerializeValue` los perdería por su switch de tipos y
// los citaría como JSON, igual que `loop` en music o `command_mode` en
// tempvoice; todo objeto/mapa/array anidado (`text`, `voice`,
// `voice_rules`, las dos listas de multiplicadores, `announce`, `rewards`,
// `rank_card`, `commands_global`, `commands`) va por `putJSONInline`
// (JSON); `updated_at` lleva el prefijo `__DATE__:` para que el viaje de
// ida y vuelta no pierda precisión (igual que tempvoice).
func MarshalModuleLeveling(m dbguild.ModuleLeveling) (map[string]string, error) {
	out := map[string]string{}
	out["schema_version"] = SerializeValue(m.SchemaVersion)
	out["enabled"] = SerializeValue(m.Enabled)
	out["enabled_since"] = nullableDateField(m.EnabledSince)
	out["xp_mode"] = string(m.XPMode)
	putJSONInline(out, "text", m.Text)
	putJSONInline(out, "voice", m.Voice)
	out["curve_multiplier"] = SerializeValue(m.CurveMultiplier)
	putJSONInline(out, "voice_rules", m.VoiceRules)
	putJSONInline(out, "excluded_channel_ids", m.ExcludedChannelIDs)
	putJSONInline(out, "excluded_role_ids", m.ExcludedRoleIDs)
	putJSONInline(out, "role_multipliers", m.RoleMultipliers)
	putJSONInline(out, "channel_multipliers", m.ChannelMultipliers)
	putJSONInline(out, "announce", m.Announce)
	putJSONInline(out, "rewards", m.Rewards)
	putJSONInline(out, "rank_card", m.RankCard)
	putJSONInline(out, "commands_global", m.CommandsGlobal)
	putJSONInline(out, "commands", m.Commands)
	out["command_mode"] = string(m.CommandMode)
	out["updated_at"] = dateField(m.UpdatedAt.Time)
	return out, nil
}

